const fs=require('fs');
global.window={}; eval(fs.readFileSync('data.js','utf8'));
const D=window.CUAD_DATA;
function esc(s){return s.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');}
function render(c, hidden={}){
  let spans=[];
  for(const cat in c.cats){ if(hidden[cat])continue; c.cats[cat].forEach(se=>spans.push({start:se[0],end:se[1],cat})); }
  if(!spans.length) return esc(c.text);
  let pts={}; spans.forEach(s=>{pts[s.start]=pts[s.end]=1;});
  const breaks=Object.keys(pts).map(Number).sort((a,b)=>a-b);
  let html=[],pos=0,active=[];
  for(const p of breaks){
    if(p>pos){ html.push(seg(c.text.slice(pos,p),active)); pos=p; }
    active=active.filter(s=>s.end>p);
    for(const s of spans){ if(s.start<=p&&p<s.end&&!active.some(a=>a.cat===s.cat&&a.end===s.end)) active.push(s); }
  }
  if(pos<c.text.length) html.push(esc(c.text.slice(pos)));
  return html.join('');
}
function seg(t,active){
  if(!active.length) return esc(t);
  const cats=[...new Set(active.map(a=>a.cat))].sort();
  return `<mark data-cats="${esc(cats.join('|'))}">${esc(t)}</mark>`;
}
// round-trip check: strip tags, unescape, must equal original text
function unescape(s){return s.replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&amp;/g,'&amp;'==='&amp;'?/&amp;/g:'&');}
